// Wochendaten fuer die LLM-Synthese aufbereiten.

const rows = $input.all().map(i => i.json).filter(r => r && r.headline);

if (rows.length === 0) {
  return [{
    json: {
      isEmpty: true,
      briefCount: 0,
      weekLabel: '',
      evidenceBlock: 'No developments recorded in this period.'
    }
  }];
}

// ---- Kalenderwoche berechnen -------------------------------------------
function isoWeek(d) {
  const date = new Date(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()));
  const dayNum = date.getUTCDay() || 7;
  date.setUTCDate(date.getUTCDate() + 4 - dayNum);
  const yearStart = new Date(Date.UTC(date.getUTCFullYear(), 0, 1));
  return Math.ceil((((date - yearStart) / 86400000) + 1) / 7);
}

const now = new Date();
const weekNumber = isoWeek(now);
const weekLabel = `Week ${weekNumber}, ${now.getFullYear()}`;

// ---- Kategorien mit lesbaren Namen --------------------------------------
const CATEGORY_LABELS = {
  regulation:  'Regulation & Policy',
  product:     'Product & Technology',
  partnership: 'Partnerships & Commercial',
  'm&a':       'M&A',
  funding:     'Funding',
  market_data: 'Market Data',
  technology:  'Product & Technology',
  other:       'Other Developments'
};

function arr(v) {
  return Array.isArray(v) ? v.filter(Boolean).map(String) : [];
}

// ---- Nach Kategorie gruppieren ------------------------------------------
const grouped = {};
for (const r of rows) {
  const key = String(r.category || 'other').toLowerCase();
  const label = CATEGORY_LABELS[key] || 'Other Developments';
  if (!grouped[label]) grouped[label] = [];
  grouped[label].push(r);
}

// ---- Evidenzblock fuer das Modell ---------------------------------------
const blocks = rows.map((r, i) => {
  return [
    `[D${i + 1}] ${r.headline}`,
    `Topic: ${r.topic} | Category: ${r.category || 'n/a'} | Event: ${r.event_type || 'n/a'}`,
    `Impact: ${r.impact_score} | Confidence: ${r.confidence_score} | Sources: ${r.source_count} (${r.tier1_count} tier-1)`,
    `Companies: ${arr(r.primary_companies).join(', ') || 'none identified'}`,
    `Segments: ${arr(r.affected_segments).join(', ') || 'n/a'}`,
    `Geography: ${arr(r.geography).join(', ') || 'n/a'}`,
    `Watch: ${arr(r.what_to_monitor).slice(0, 3).join(' | ') || 'n/a'}`,
    `Summary: ${String(r.summary || '').slice(0, 700)}`
  ].join('\n');
});

// ---- Kennzahlen ---------------------------------------------------------
const allCompanies = new Set();
const allSegments = new Set();
for (const r of rows) {
  arr(r.primary_companies).forEach(c => allCompanies.add(c));
  arr(r.affected_segments).forEach(s => allSegments.add(s));
}

const avg = (f) => {
  const vals = rows.map(r => Number(r[f])).filter(Number.isFinite);
  return vals.length ? Math.round(vals.reduce((a, b) => a + b, 0) / vals.length) : 0;
};

return [{
  json: {
    isEmpty: false,
    weekLabel,
    weekNumber,
    generatedAt: now.toISOString(),
    briefCount: rows.length,
    categoryCount: Object.keys(grouped).length,
    companyCount: allCompanies.size,
    companies: Array.from(allCompanies).sort(),
    segments: Array.from(allSegments).sort(),
    avgImpact: avg('impact_score'),
    avgConfidence: avg('confidence_score'),
    totalSources: rows.reduce((s, r) => s + (Number(r.source_count) || 0), 0),
    totalTier1: rows.reduce((s, r) => s + (Number(r.tier1_count) || 0), 0),
    categories: Object.keys(grouped),
    grouped,
    rows,
    evidenceBlock: blocks.join('\n\n---\n\n')
  }
}];

// Markdown-Report in eine schlichte, mailtaugliche HTML-Seite giessen.

const llm = $input.first().json;
const ctx = $('Group by Category').first().json;

const md = String(llm.text || llm.response || '').trim();

// --- Minimaler Markdown-Konverter (reicht fuer unsere Struktur) ---------
function mdToHtml(src) {
  const lines = src.split('\n');
  const out = [];
  let inList = false;

  const inline = (s) => s
    .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;')
    .replace(/\*\*(.+?)\*\*/g, '<strong>$1</strong>')
    .replace(/\*(.+?)\*/g, '<em>$1</em>');

  for (const raw of lines) {
    const line = raw.trim();

    if (line === '---' || line === '') {
      if (inList) { out.push('</ul>'); inList = false; }
      continue;
    }
    if (line.startsWith('### ')) {
      if (inList) { out.push('</ul>'); inList = false; }
      out.push(`<h3>${inline(line.slice(4))}</h3>`);
    } else if (line.startsWith('## ')) {
      if (inList) { out.push('</ul>'); inList = false; }
      out.push(`<h2>${inline(line.slice(3))}</h2>`);
    } else if (/^\d+\.\s/.test(line) || line.startsWith('- ')) {
      if (!inList) { out.push('<ul>'); inList = true; }
      out.push(`<li>${inline(line.replace(/^\d+\.\s|^-\s/, ''))}</li>`);
    } else {
      if (inList) { out.push('</ul>'); inList = false; }
      out.push(`<p>${inline(line)}</p>`);
    }
  }
  if (inList) out.push('</ul>');
  return out.join('\n');
}

const body = mdToHtml(md);
const dateStr = new Date().toISOString().slice(0, 10);

const html = `<!DOCTYPE html>
<html lang="en"><head><meta charset="utf-8">
<title>Payments Intelligence — ${ctx.weekLabel}</title></head>
<body style="margin:0;padding:0;background:#f5f5f4;">
<div style="max-width:680px;margin:0 auto;padding:32px 24px;background:#ffffff;
            font-family:-apple-system,Segoe UI,Helvetica,Arial,sans-serif;
            font-size:15px;line-height:1.6;color:#1c1917;">

  <div style="border-bottom:2px solid #1c1917;padding-bottom:14px;margin-bottom:26px;">
    <div style="font-size:12px;letter-spacing:1.5px;text-transform:uppercase;color:#78716c;">
      Payments Intelligence
    </div>
    <div style="font-size:26px;font-weight:600;margin-top:6px;">${ctx.weekLabel}</div>
    <div style="font-size:13px;color:#78716c;margin-top:6px;">
      ${ctx.briefCount} developments · ${ctx.totalSources} sources
      (${ctx.totalTier1} tier-1) · ${ctx.companyCount} companies · generated ${dateStr}
    </div>
  </div>

  ${body}

  <div style="border-top:1px solid #e7e5e4;margin-top:32px;padding-top:16px;
              font-size:12px;color:#78716c;">
    Generated automatically from ${ctx.briefCount} analysed developments.
    Impact and confidence scores are model-assigned; confidence reflects source
    count, source tier and whether full article text was retrieved.
    Low-confidence items are flagged and should be verified before acting on them.
  </div>
</div></body></html>`;

return [{
  json: {
    week_label: ctx.weekLabel,
    week_number: ctx.weekNumber,
    brief_count: ctx.briefCount,
    subject: `Payments Intelligence — ${ctx.weekLabel}`,
    report_markdown: md,
    report_html: html
  }
}];
